LOCATION_NAME_ID_REGION = []
seen = set()

def constructLNIDR(list, index):
    for _, apName, _ in list:
        name = apName[0]
        if(name in seen):
            continue
        seen.add(name)
        region = name.split(":", 1)[0]
        LOCATION_NAME_ID_REGION.append([name, index, region])
        index += 1

constructLNIDR(DOS2_LOCATION_LIST, 1)
constructLNIDR(DOS2_CHEST_LIST, 1000)
constructLNIDR(DOS2_EVERYTHING_LIST, 2000)

